//! Poppler runs in a cancellable child process: no PDF parsing on the UI thread.
use super::process::{execute, execute_limited, program};
use crate::domain::error::AppError;
use sha2::{Digest, Sha256};
use std::{
    fs,
    path::Path,
    process::Command,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::UNIX_EPOCH,
};

pub use crate::policy::{edge_bucket, DISK_BUDGET, PAGE_EDGE, THUMB_EDGE};

pub use crate::domain::document::PdfLink;

/// Read a Poppler XML attribute. Output is generated by pdftohtml, not user-authored XML.
fn xml_attr<'a>(tag: &'a str, name: &str) -> Option<&'a str> {
    let prefix = format!("{name}=\"");
    let rest = tag.get(tag.find(&prefix)? + prefix.len()..)?;
    rest.get(..rest.find('"')?)
}

fn internal_page(href: &str, total: u32) -> Option<u32> {
    let (file, fragment) = href.rsplit_once('#')?;
    // pdftohtml resolves PDF GoTo destinations to same-document .html#PAGE links.
    // Do not treat an external URL with a numeric anchor as a PDF page jump.
    if file.contains("://")
        || file.contains('/')
        || file.contains('\\')
        || (!file.is_empty() && !file.to_ascii_lowercase().ends_with(".html"))
    {
        return None;
    }
    let number = fragment.strip_prefix("page=").unwrap_or(fragment);
    number
        .parse::<u32>()
        .ok()
        .filter(|page| (1..=total).contains(page))
}

fn parse_page_links(xml: &str, page: u32, total: u32) -> Vec<PdfLink> {
    let mut links = Vec::new();
    let mut remaining = xml;
    while let Some(start) = remaining.find("<page ") {
        remaining = &remaining[start..];
        let Some(header_end) = remaining.find('>') else {
            break;
        };
        let header = &remaining[..header_end];
        let Some(end) = remaining.find("</page>") else {
            break;
        };
        let page_content = &remaining[header_end + 1..end];
        remaining = &remaining[end + "</page>".len()..];
        if xml_attr(header, "number").and_then(|v| v.parse::<u32>().ok()) != Some(page) {
            continue;
        }
        let width = xml_attr(header, "width").and_then(|v| v.parse::<f32>().ok());
        let height = xml_attr(header, "height").and_then(|v| v.parse::<f32>().ok());
        let (Some(width), Some(height)) = (width, height) else {
            break;
        };
        if !width.is_finite() || !height.is_finite() || width <= 0.0 || height <= 0.0 {
            break;
        }
        let page_left = xml_attr(header, "left")
            .and_then(|v| v.parse().ok())
            .unwrap_or(0.0);
        let page_top = xml_attr(header, "top")
            .and_then(|v| v.parse().ok())
            .unwrap_or(0.0);
        let mut text = page_content;
        while let Some(text_start) = text.find("<text ") {
            text = &text[text_start..];
            let Some(text_header_end) = text.find('>') else {
                break;
            };
            let Some(text_end) = text.find("</text>") else {
                break;
            };
            let text_header = &text[..text_header_end];
            let body = &text[text_header_end + 1..text_end];
            text = &text[text_end + "</text>".len()..];
            let coords = ["left", "top", "width", "height"]
                .map(|key| xml_attr(text_header, key).and_then(|v| v.parse::<f32>().ok()));
            let [Some(left), Some(top), Some(box_width), Some(box_height)] = coords else {
                continue;
            };
            let bounds = [
                ((left - page_left) / width).clamp(0.0, 1.0),
                ((top - page_top) / height).clamp(0.0, 1.0),
                ((left + box_width - page_left) / width).clamp(0.0, 1.0),
                ((top + box_height - page_top) / height).clamp(0.0, 1.0),
            ];
            if !bounds.iter().all(|n| n.is_finite())
                || bounds[2] <= bounds[0]
                || bounds[3] <= bounds[1]
            {
                continue;
            }
            let mut anchors = body;
            while let Some(anchor_start) = anchors.find("<a ") {
                anchors = &anchors[anchor_start..];
                let Some(anchor_header_end) = anchors.find('>') else {
                    break;
                };
                let anchor_header = &anchors[..anchor_header_end];
                anchors = &anchors[anchor_header_end + 1..];
                let Some(target_page) =
                    xml_attr(anchor_header, "href").and_then(|href| internal_page(href, total))
                else {
                    continue;
                };
                links.push(PdfLink {
                    left: bounds[0],
                    top: bounds[1],
                    right: bounds[2],
                    bottom: bounds[3],
                    target_page,
                });
            }
        }
        break;
    }
    links
}

/// Extract text-link hit areas and resolved page destinations on a worker thread.
/// Requires pdftohtml, supplied by the same Poppler suite as pdftoppm/pdfinfo.
pub fn page_links(
    path: &Path,
    page: u32,
    total: u32,
    generation: &Arc<AtomicU64>,
    expected: u64,
) -> Result<Vec<PdfLink>, AppError> {
    let mut command = Command::new(program("pdftohtml"));
    command.args([
        "-q",
        "-xml",
        "-noroundcoord",
        "-i",
        "-f",
        &page.to_string(),
        "-l",
        &page.to_string(),
        "-stdout",
    ]);
    command.arg(path);
    let bytes = execute(command, generation, expected)?;
    Ok(parse_page_links(
        &String::from_utf8_lossy(&bytes),
        page,
        total,
    ))
}

pub fn page_count(
    path: &Path,
    generation: &Arc<AtomicU64>,
    expected: u64,
) -> Result<u32, AppError> {
    if !path.is_file() {
        return Err("This PDF is no longer available.".into());
    }
    let mut command = Command::new(program("pdfinfo"));
    command.env("LC_ALL", "C").arg(path);
    let bytes = execute(command, generation, expected)?;
    String::from_utf8_lossy(&bytes)
        .lines()
        .find_map(|l| {
            l.strip_prefix("Pages:")
                .and_then(|n| n.trim().parse::<u32>().ok())
        })
        .filter(|n| *n > 0)
        .ok_or_else(|| "The document has no readable pages.".into())
}
fn key(path: &Path) -> Result<String, AppError> {
    let m = fs::metadata(path).map_err(|e| AppError::from(e.to_string()))?;
    let mut hash = Sha256::new();
    hash.update(path.as_os_str().as_encoded_bytes());
    hash.update(m.len().to_le_bytes());
    hash.update(
        m.modified()
            .map_err(|e| AppError::from(e.to_string()))?
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos()
            .to_le_bytes(),
    );
    Ok(format!("{:x}", hash.finalize()))
}
fn decode(path: &Path) -> Result<image::RgbaImage, AppError> {
    let mut reader = image::ImageReader::open(path)
        .map_err(|e| AppError::from(e.to_string()))?
        .with_guessed_format()
        .map_err(|e| AppError::from(e.to_string()))?;
    let mut limits = image::Limits::default();
    limits.max_image_width = Some(PAGE_EDGE);
    limits.max_image_height = Some(PAGE_EDGE);
    limits.max_alloc = Some(64 * 1024 * 1024);
    reader.limits(limits);
    reader
        .decode()
        .map(|i| i.to_rgba8())
        .map_err(|e| AppError::from(e.to_string()))
}
pub fn raster(
    path: &Path,
    page: u32,
    edge: u32,
    cache: &Path,
    generation: &Arc<AtomicU64>,
    expected: u64,
) -> Result<image::RgbaImage, AppError> {
    if !(1..=PAGE_EDGE).contains(&edge) || page == 0 {
        return Err("Invalid render dimensions or page.".into());
    }
    let thumb = edge == THUMB_EDGE && page == 1;
    // Cached reading pages are keyed by file fingerprint, page AND resolution.
    // The original thumbnail cache filename is preserved for backward compatibility.
    let cached = key(path).ok().map(|key| {
        if thumb {
            cache.join(format!("{key}.png"))
        } else {
            cache.join(format!("{key}-p{page}-e{edge}.png"))
        }
    });
    if let Some(p) = &cached {
        if let Ok(image) = decode(p) {
            if image.width().max(image.height()) <= edge {
                return Ok(image);
            }
        }
    }
    // Cache failure must never prevent viewing a document.
    let temp = tempfile::tempdir().map_err(|e| AppError::from(e.to_string()))?;
    let prefix = temp.path().join("page");
    let mut command = Command::new(program("pdftoppm"));
    command
        .args([
            "-f",
            &page.to_string(),
            "-l",
            &page.to_string(),
            "-singlefile",
            "-scale-to",
            &edge.to_string(),
            "-png",
        ])
        .arg(path)
        .arg(&prefix);
    execute(command, generation, expected)?;
    let output = prefix.with_extension("png");
    let result = decode(&output)?;
    if result.width().max(result.height()) > edge {
        return Err(AppError::InvalidDocument(
            "Rendered image exceeds the requested pixel budget.".into(),
        ));
    }
    if let Some(p) = cached {
        if generation.load(Ordering::Acquire) == expected && fs::create_dir_all(cache).is_ok() {
            // Write a unique temporary file and atomically rename it into the cache.
            // Interrupted rendering never leaves a partial PNG at its final name.
            let temp_name = cache.join(format!(
                "{}.{}.tmp",
                p.file_name().unwrap_or_default().to_string_lossy(),
                std::process::id()
            ));
            if fs::copy(&output, &temp_name).is_ok() && fs::rename(&temp_name, &p).is_err() {
                // Windows cannot rename over a corrupt existing cache entry.
                let _ = fs::remove_file(&p);
                let _ = fs::rename(&temp_name, p);
            }
            let _ = fs::remove_file(temp_name);
        }
    }
    Ok(result)
}
pub use crate::infrastructure::disk_cache::trim_cache;

pub struct Poppler;
impl crate::services::ports::PdfEngine for Poppler {
    fn page_count(
        &self,
        path: &Path,
        generation: &Arc<AtomicU64>,
        expected: u64,
    ) -> Result<u32, AppError> {
        page_count(path, generation, expected)
    }
    fn geometry(
        &self,
        path: &Path,
        total: u32,
        generation: &Arc<AtomicU64>,
        expected: u64,
    ) -> Result<Vec<crate::domain::document::PageGeometry>, AppError> {
        page_geometry(path, total, generation, expected)
    }
    fn raster(
        &self,
        path: &Path,
        page: u32,
        edge: u32,
        cache: &Path,
        generation: &Arc<AtomicU64>,
        expected: u64,
    ) -> Result<image::RgbaImage, AppError> {
        raster(path, page, edge, cache, generation, expected)
    }
    fn text(
        &self,
        path: &Path,
        page: u32,
        geometry: crate::domain::document::PageGeometry,
        generation: &Arc<AtomicU64>,
        expected: u64,
    ) -> Result<Vec<crate::domain::annotation::TextWord>, AppError> {
        let mut command = Command::new(program("pdftotext"));
        command
            .args(["-bbox", "-f", &page.to_string(), "-l", &page.to_string()])
            .arg(path)
            .arg("-");
        let bytes = execute(command, generation, expected)?;
        parse_text(&String::from_utf8_lossy(&bytes), Some(geometry))
    }
    fn links(
        &self,
        path: &Path,
        page: u32,
        total: u32,
        generation: &Arc<AtomicU64>,
        expected: u64,
    ) -> Result<Vec<PdfLink>, AppError> {
        page_links(path, page, total, generation, expected)
    }
}

/// One bounded metadata command; no per-page rasterization or UI-thread PDF work.
pub fn page_geometry(
    path: &Path,
    total: u32,
    generation: &Arc<AtomicU64>,
    expected: u64,
) -> Result<Vec<crate::domain::document::PageGeometry>, AppError> {
    if !(1..=crate::policy::MAX_DOCUMENT_PAGES).contains(&total) {
        return Err(format!(
            "Documents above {} pages are not supported.",
            crate::policy::MAX_DOCUMENT_PAGES
        )
        .into());
    }
    let mut command = Command::new(program("pdfinfo"));
    command
        .env("LC_ALL", "C")
        .args(["-box", "-f", "1", "-l", &total.to_string()])
        .arg(path);
    let bytes = execute_limited(command, generation, expected, 16 * 1024 * 1024)?;
    parse_geometry(&String::from_utf8_lossy(&bytes), total)
}
fn parse_geometry(
    text: &str,
    total: u32,
) -> Result<Vec<crate::domain::document::PageGeometry>, AppError> {
    let mut dimensions = vec![None; total as usize];
    let mut rotations = vec![0; total as usize];
    for line in text.lines() {
        let words: Vec<_> = line.split_whitespace().collect();
        if words.first() != Some(&"Page") {
            continue;
        }
        let Some(index) = words
            .get(1)
            .and_then(|n| n.parse::<usize>().ok())
            .and_then(|n| n.checked_sub(1))
            .filter(|n| *n < total as usize)
        else {
            continue;
        };
        if words.get(2) == Some(&"MediaBox:") {
            let values: Option<Vec<f32>> = words
                .iter()
                .skip(3)
                .take(4)
                .map(|value| value.parse::<f32>().ok())
                .collect();
            if let Some(values) = values.filter(|v| v.len() == 4) {
                dimensions[index] = Some((values[2] - values[0], values[3] - values[1]));
            }
        }
        if words.get(2) == Some(&"rot:") {
            rotations[index] = words
                .get(3)
                .and_then(|r| r.parse::<i32>().ok())
                .unwrap_or(0);
        }
    }
    dimensions
        .into_iter()
        .zip(rotations)
        .map(|(size, rotation)| {
            size.and_then(|(w, h)| crate::domain::document::PageGeometry::new(w, h, rotation))
                .ok_or_else(|| "PDF page dimensions are missing or invalid.".into())
        })
        .collect()
}

#[cfg(test)]
mod link_tests {
    use super::*;

    #[test]
    fn poppler_internal_link_text_resolves_pages_and_rectangles() {
        let xml = r##"<pdf2xml>
<page number="1" top="0" left="0" width="900" height="1200">
<text top="180" left="90" width="180" height="24"><a href="book.html#2">Chapter 2</a></text>
<text top="230" left="90" width="180" height="24"><a href="book.html#3">Chapter 3</a></text>
<text top="300" left="90" width="180" height="24"><a href="https://example.com#4">External</a></text>
</page></pdf2xml>"##;
        let links = parse_page_links(xml, 1, 3);
        assert_eq!(links.len(), 2);
        assert_eq!(links[0].target_page, 2);
        assert!((links[0].left - 0.1).abs() < 0.00001);
        assert!((links[0].top - 0.15).abs() < 0.00001);
        assert_eq!(links[1].target_page, 3);
        assert!(parse_page_links(xml, 2, 3).is_empty());
        assert_eq!(parse_page_links(xml, 1, 2).len(), 1);
    }

    #[test]
    fn raster_buckets_limit_repeated_work() {
        assert_eq!(edge_bucket(850.0), 896);
        assert_eq!(edge_bucket(851.0), 896);
        assert_eq!(edge_bucket(4000.0), PAGE_EDGE);
        assert_eq!(edge_bucket(f32::NAN), 1152);
    }

    #[test]
    fn rejects_invalid_destinations_and_bounds() {
        assert_eq!(internal_page("guide.html#page=12", 12), Some(12));
        assert_eq!(internal_page("guide.html#0", 12), None);
        assert_eq!(internal_page("guide.html#13", 12), None);
        assert_eq!(internal_page("https://example.com/path#3", 12), None);
        let xml = r##"<page number="2" width="0" height="500"><text left="2" top="1" width="3" height="3"><a href="#1">Item</a></text></page>"##;
        assert!(parse_page_links(xml, 2, 5).is_empty());
    }
}

/// Poppler bbox output is XHTML with word boxes in displayed page coordinates.
fn parse_text(
    xml: &str,
    geometry: Option<crate::domain::document::PageGeometry>,
) -> Result<Vec<crate::domain::annotation::TextWord>, AppError> {
    let page = xml
        .find("<page ")
        .and_then(|i| xml.get(i..))
        .ok_or_else(|| AppError::InvalidDocument("Missing text page dimensions.".into()))?;
    let end = page
        .find('>')
        .ok_or_else(|| AppError::InvalidDocument("Invalid text page.".into()))?;
    let dimension = |name| {
        xml_attr(&page[..end], name)
            .and_then(|v| v.parse::<f32>().ok())
            .filter(|v| v.is_finite() && *v > 0.0)
    };
    let (Some(width), Some(height)) = (dimension("width"), dimension("height")) else {
        return Err(AppError::InvalidDocument("Invalid text dimensions.".into()));
    };
    // pdftotext reports unrotated dimensions but rotates word coordinates.
    let (width, height) = geometry
        .map(|g| (g.width, g.height))
        .unwrap_or((width, height));
    let mut words = Vec::new();
    let mut rest = &page[end + 1..];
    while let Some(start) = rest.find("<word ") {
        rest = &rest[start..];
        let Some(end) = rest.find('>') else {
            break;
        };
        let Some(close) = rest.find("</word>") else {
            break;
        };
        let coords = ["xMin", "yMin", "xMax", "yMax"]
            .map(|name| xml_attr(&rest[..end], name).and_then(|v| v.parse::<f32>().ok()));
        if let [Some(l), Some(t), Some(r), Some(b)] = coords {
            let bounds = [l / width, t / height, r / width, b / height].map(|v| v.clamp(0.0, 1.0));
            if bounds.iter().all(|v| v.is_finite())
                && bounds[0] < bounds[2]
                && bounds[1] < bounds[3]
            {
                words.push(crate::domain::annotation::TextWord {
                    text: decode_xml(&rest[end + 1..close]),
                    bounds,
                });
            }
        }
        rest = &rest[close + 7..];
    }
    Ok(words)
}
fn decode_xml(text: &str) -> String {
    let mut out = String::new();
    let mut rest = text;
    while let Some(start) = rest.find('&') {
        out.push_str(&rest[..start]);
        rest = &rest[start..];
        let Some(end) = rest.find(';') else {
            break;
        };
        let entity = &rest[1..end];
        let ch = match entity {
            "amp" => Some('&'),
            "lt" => Some('<'),
            "gt" => Some('>'),
            "quot" => Some('"'),
            "apos" => Some('\''),
            _ => entity
                .strip_prefix("#x")
                .and_then(|n| u32::from_str_radix(n, 16).ok())
                .or_else(|| entity.strip_prefix('#').and_then(|n| n.parse().ok()))
                .and_then(char::from_u32),
        };
        if let Some(ch) = ch {
            out.push(ch);
        } else {
            out.push_str(&rest[..=end]);
        }
        rest = &rest[end + 1..];
    }
    out.push_str(rest);
    out
}

#[cfg(test)]
mod text_tests {
    use super::*;
    use crate::services::ports::PdfEngine;
    #[test]
    fn normalizes_word_bounds_and_decodes_entities() {
        let words=parse_text(r#"<page width="400" height="800"><word xMin="40" yMin="80" xMax="200" yMax="100">A&amp;B &#x1F600; &#233;</word><word xMin="NaN" yMin="0" xMax="20" yMax="10">bad</word></page>"#, None).unwrap();
        assert_eq!(words.len(), 1);
        assert_eq!(words[0].text, "A&B 😀 é");
        assert_eq!(words[0].bounds, [0.1, 0.1, 0.5, 0.125]);
        assert!(parse_text(r#"<page width="0" height="800"></page>"#, None).is_err());
        assert!(
            parse_text(r#"<page width="400" height="800"></page>"#, None)
                .unwrap()
                .is_empty()
        );
    }
    #[test]
    #[ignore = "Requires Poppler executables on PATH"]
    fn extracts_only_requested_fixture_page_and_honors_cancellation() {
        let generation = Arc::new(AtomicU64::new(1));
        let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/sample.pdf");
        let words = Poppler
            .text(
                &path,
                2,
                crate::domain::document::PageGeometry {
                    width: 400.0,
                    height: 550.0,
                },
                &generation,
                1,
            )
            .unwrap();
        assert_eq!(
            words
                .iter()
                .map(|w| w.text.as_str())
                .collect::<Vec<_>>()
                .join(" "),
            "Folio test document Page 2 of 3"
        );
        assert!(matches!(
            Poppler.text(
                &path,
                2,
                crate::domain::document::PageGeometry {
                    width: 400.0,
                    height: 550.0
                },
                &generation,
                0
            ),
            Err(AppError::Cancelled)
        ));
    }
}
